import functools
import inspect
from typing import Callable, Any, ForwardRef
from fastapi import FastAPI, Depends
from fastapi.dependencies.utils import get_typed_signature

# We define a class in a different "scope" (conceptually) 
# but for the test we just need to show that forward refs 
# in a wrapped function fail if we don't go to the original globals.

class Target:
    def __init__(self):
        self.x = 1

def wrapper(func: Callable) -> Callable:
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

# Define the function. The forward reference 'Target' is in this module's globals.
def endpoint_func(item: 'Target'):
    return item

# Wrap it
wrapped_endpoint = wrapper(endpoint_func)

def test_wrapped_method_type_inference():
    # This should not raise NameError now
    try:
        sig = get_typed_signature(wrapped_endpoint)
        # Check if the annotation was resolved to Target
        param = sig.parameters['item']
        assert param.annotation is Target
    except NameError as e:
        raise AssertionError(f"NameError raised: {e}") from e

if __name__ == "__main__":
    test_wrapped_method_type_inference()
    print("Test passed!")
